import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        // dp[v]: longest valid chain ending with right value v
        int[] dp = new int[7];
        for (int i = 0; i < n; i++) {
            int left = nextInt(), right = nextInt();
            dp[right] = Math.max(dp[right], dp[left] + 1);
        }
        int best = 0;
        for (int v : dp) best = Math.max(best, v);
        System.out.println(n - best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// dp[v]: longest valid chain ending with right value v
	var dp [7]int
	for i := 0; i < n; i++ {
		left, right := nextInt(), nextInt()
		dp[right] = max(dp[right], dp[left]+1)
	}
	best := 0
	for _, v := range dp {
		best = max(best, v)
	}
	fmt.Println(n - best)
}
